components.MissingDocsTable:
export default function MissingDocsTable({ rows }: { rows: any[] }) {
  const data = Array.isArray(rows) ? rows : [];
  const missing = data.filter((r: any) => {
    const status = (r.status ?? "").toLowerCase();
    return (
      status === "missing_docs" ||
      status === "missing docs" ||
      status === "outstanding" ||
      (r.progress && typeof r.progress.received === "number" && typeof r.progress.total === "number" && r.progress.received < r.progress.total)
    );
  });

  function humanizeEntity(raw: string): string {
    if (!raw) return "—";
    const map: Record<string, string> = {
      s_corp: "S-Corp",
      s_corporation: "S-Corp",
      c_corp: "C-Corp",
      c_corporation: "C-Corp",
      sole_prop: "Sole Prop",
      sole_proprietor: "Sole Prop",
      partnership: "Partnership",
      llc: "LLC",
      individual: "Individual",
    };
    return map[raw.toLowerCase()] ?? raw;
  }

  function humanizeStatus(raw: string): string {
    if (!raw) return "—";
    const map: Record<string, string> = {
      missing_docs: "Missing docs",
      outstanding: "Outstanding",
      review: "Needs review",
      verified: "Verified",
      complete: "Complete",
      overdue: "Overdue",
    };
    return map[raw.toLowerCase()] ?? raw.replace(/_/g, " ");
  }

  function deadlineLabel(iso: string): string {
    if (!iso) return "—";
    const now = new Date("2026-08-03");
    const d = new Date(iso);
    const diff = Math.round((d.getTime() - now.getTime()) / 86400000);
    const formatted = d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
    if (diff < 0) return `${formatted} (${Math.abs(diff)}d overdue)`;
    if (diff === 0) return `${formatted} (today)`;
    if (diff <= 7) return `${formatted} (${diff}d away)`;
    return formatted;
  }

  if (missing.length === 0) {
    return (
      <div style={{ padding: "24px 0", color: "var(--vendo-color-muted)", fontFamily: "var(--vendo-font-family)", fontSize: "var(--vendo-font-size)" }}>
        No clients with outstanding documents — nothing to chase this week.
      </div>
    );
  }

  const sorted = [...missing].sort((a: any, b: any) => {
    const da = a.filingDeadline ? new Date(a.filingDeadline).getTime() : Infinity;
    const db = b.filingDeadline ? new Date(b.filingDeadline).getTime() : Infinity;
    return da - db;
  });

  const statusColor: Record<string, string> = {
    "Missing docs": "var(--vendo-color-danger)",
    "Overdue": "var(--vendo-color-danger)",
    "Needs review": "#b07a00",
    "Outstanding": "var(--vendo-color-muted)",
  };

  return (
    <div style={{ overflowX: "auto", fontFamily: "var(--vendo-font-family)", fontSize: "var(--vendo-font-size)" }}>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr style={{ borderBottom: "1px solid var(--vendo-color-border)" }}>
            {["Client", "Contact", "Entity", "Filing deadline", "Docs", "Status", "Assigned to"].map((h) => (
              <th key={h} style={{ textAlign: "left", padding: "10px 12px", color: "var(--vendo-color-muted)", fontWeight: 500, whiteSpace: "nowrap" }}>{h}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {sorted.map((r: any, i: number) => {
            const received = typeof r.progress?.received === "number" ? r.progress.received : null;
            const total = typeof r.progress?.total === "number" ? r.progress.total : null;
            const docsLabel = received !== null && total !== null ? `${received} of ${total}` : "—";
            const statusHuman = humanizeStatus(r.status ?? "");
            const sColor = statusColor[statusHuman] ?? "var(--vendo-color-text)";
            return (
              <tr key={i} style={{ borderBottom: "1px solid var(--vendo-color-border)", background: i % 2 === 0 ? "transparent" : "rgba(0,0,0,0.015)" }}>
                <td style={{ padding: "12px 12px", fontWeight: 500, color: "var(--vendo-color-text)" }}>{r.businessName || "—"}</td>
                <td style={{ padding: "12px 12px", color: "var(--vendo-color-text)" }}>{r.contactName || "—"}</td>
                <td style={{ padding: "12px 12px", color: "var(--vendo-color-muted)" }}>{humanizeEntity(r.entityType ?? "")}</td>
                <td style={{ padding: "12px 12px", color: "var(--vendo-color-text)", whiteSpace: "nowrap" }}>{deadlineLabel(r.filingDeadline ?? "")}</td>
                <td style={{ padding: "12px 12px", color: "var(--vendo-color-muted)" }}>{docsLabel}</td>
                <td style={{ padding: "12px 12px" }}>
                  <span style={{ display: "inline-block", padding: "2px 10px", borderRadius: "var(--vendo-radius-small)", background: sColor === "var(--vendo-color-danger)" ? "rgba(176,71,58,0.1)" : "rgba(0,0,0,0.06)", color: sColor, fontWeight: 500, fontSize: "0.875em" }}>{statusHuman}</span>
                </td>
                <td style={{ padding: "12px 12px", color: "var(--vendo-color-muted)" }}>{r.assignee?.name || "—"}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
